        if not sep:
            raise ValueError("empty separator")
        m = len(sep)
        parts, start, i = [], 0, 0
        while i <= len(s) - m:
            if s[i:i + m] == sep:                   # separator starts at i
                parts.append(s[start:i])            # may be "" between adjacent separators
