        if root is None:
            return []
        result: List[List[int]] = []
        queue = deque([root])
        while queue:
            level = []
            for _ in range(len(queue)):       # snapshot: exactly the nodes of this level
                node = queue.popleft()
                level.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            result.append(level)
        return result

