        path: List[int] = []

        def dfs(start: int) -> None:
            result.append(path[:])             # every node of the tree is a subset
            for i in range(start, len(nums)):
                path.append(nums[i])           # choose
                dfs(i + 1)                     # explore (indices only increase: no dups)
                path.pop()                     # un-choose

        dfs(0)
        return result

