class BruteForce:
    """Keep the whole stream; re-sum the last `size` values on each call, O(size)."""

    def __init__(self, size: int):
        self.size = size
        self.seen = []

    def next(self, val: int) -> float:
        self.seen.append(val)
        tail = self.seen[-self.size:]
        return sum(tail) / len(tail)

