        fail = [0] * len(s)                          # fail[i] = longest proper border of s[:i+1]
        for i in range(1, len(s)):
            k = fail[i - 1]
            while k and s[i] != s[k]:                # shrink to the border of the border
                k = fail[k - 1]
            if s[i] == s[k]:
                k += 1
            fail[i] = k
        return s[:fail[-1]]

