    def evaluate(expr: str) -> int:
        total, sign, i = 0, 1, 0
        while i < len(expr):
            c = expr[i]
            if c.isdigit():
                j = i
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                total, i = total + sign * int(expr[i:j]), j
                continue
            if c == "(":                             # look ahead for the matching ")"
                depth, j = 0, i
                while True:
                    depth += (expr[j] == "(") - (expr[j] == ")")
                    if depth == 0:
                        break
                    j += 1
                total, i = total + sign * evaluate(expr[i + 1:j]), j   # re-reads the inside
            elif c in "+-":
                sign = 1 if c == "+" else -1
            i += 1
        return total
    return evaluate(s)

