        def dfs(node: Optional[TreeNode], row: int, col: int) -> None:
            if node is None:
                return
            cols[col].append((row, node.val))
            dfs(node.left, row + 1, col - 1)
            dfs(node.right, row + 1, col + 1)

        dfs(root, 0, 0)
        # tuple sort = by row, then by value for nodes sharing the same (row, col)
