def brute_force(s1: str, s2: str) -> int:
    # BFS over ALL swaps: n(n-1)/2 neighbours per state, up to n! states -> exponential.
    n = len(s1)
    queue = deque([(s1, 0)])
    seen = {s1}
    while queue:
        cur, d = queue.popleft()
        if cur == s2:
            return d
        for i in range(n):
            for j in range(i + 1, n):
                lst = list(cur)
                lst[i], lst[j] = lst[j], lst[i]
                nxt = "".join(lst)
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append((nxt, d + 1))
    return -1

