                i = 0
                while cur[i] == s2[i]:           # first mismatch: it must be fixed eventually
                    i += 1
                for j in range(i + 1, len(cur)):
                    if cur[j] == s2[i] and cur[j] != s2[j]:   # fixes i, does not break j
