def brute_force(headA: ListNode, headB: ListNode) -> Optional[ListNode]:
    a = headA
    while a:
        b = headB
        while b:                      # rescans all of B for every node of A
            if a is b:
                return a
            b = b.next
        a = a.next
    return None

