class BruteForce:
    """Two queues; every pop/top moves n-1 items across to reach the newest, O(n)."""

    def __init__(self):
        self.q1, self.q2 = deque(), deque()

    def push(self, x: int) -> None:
        self.q1.append(x)

    def _drain(self) -> int:
        while len(self.q1) > 1:
            self.q2.append(self.q1.popleft())
        last = self.q1.popleft()
        self.q1, self.q2 = self.q2, self.q1
        return last

    def pop(self) -> int:
        return self._drain()

    def top(self) -> int:
        last = self._drain()
        self.q1.append(last)
        return last

    def empty(self) -> bool:
        return not self.q1

